<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import { ArrowDown } from '@element-plus/icons-vue';
import { apiRequest } from '../../lib/api.js';
const props = defineProps({ kind: String, accounts: { type: Array, default: () => [] }, initial: Object, saving: Boolean, error: String });
const emit = defineEmits(['close', 'save']);
const group = computed(() => props.kind === '群聊自动回复'), localError = ref(''); let nextId = 100;
const initial = props.initial;
const form = reactive({ name: initial?.name || '', trigger: initial?.trigger || (group.value ? 'any' : 'first'), keywords: (initial?.keywords || []).join('\n'), account: initial?.account || '', dailyLimit: initial?.daily_limit ?? (group.value ? '' : 1), delay: initial?.delay || 0, cooldown: initial?.cooldown || 0, groups: initial?.groups ? [...initial.groups] : [], enabled: initial?.enabled ?? true, components: initial?.components?.map((item, index) => ({ id: index + 1, type: 'text', ...item })) || [{ id: 1, type: 'text', text: '', mode: 'whole' }] });
const typeLabels = { text: '文本回复', emoji: '表情回复', card: '卡片回复', image: '图片回复' };
// 前三个是抖音自带的图片表情，其余按文本表情发送。
const emojis = [{ name: '嗨', glyph: '👋' }, { name: '比心', glyph: '🫶' }, { name: '续火花', glyph: '🔥' }, { name: '微笑', glyph: '🙂' }, { name: '大笑', glyph: '😄' }, { name: '爱心', glyph: '❤️' }, { name: '点赞', glyph: '👍' }, { name: '庆祝', glyph: '🎉' }, { name: '惊讶', glyph: '😮' }, { name: '哭泣', glyph: '😢' }, { name: '生气', glyph: '😡' }, { name: 'OK', glyph: '👌' }];
const cards = ref([]), uploading = ref(false);
onMounted(async () => { try { cards.value = await apiRequest('cards'); } catch { cards.value = []; } });
// 群聊规则：监听群聊候选项来自所选账号已同步的群会话（保存的是会话 ID，后端同时兼容群名称）。
const groupOptions = ref([]);
async function loadGroups() {
  if (!group.value || !form.account) { groupOptions.value = []; return; }
  try { groupOptions.value = (await apiRequest(`conversations?account=${encodeURIComponent(form.account)}`)).filter(row => row.type === 'group').map(row => ({ value: row.id, label: row.title || '未命名群聊' })); }
  catch { groupOptions.value = []; }
}
watch(() => form.account, loadGroups, { immediate: true });
function addComponent(type) { const base = { id: nextId++, type }; form.components.push(type === 'text' ? { ...base, text: '', mode: 'whole' } : type === 'emoji' ? { ...base, name: '', glyph: '' } : type === 'card' ? { ...base, cardId: '' } : { ...base, imageId: '', name: '', preview: '' }); }
function pickEmoji(item, emoji) { item.name = emoji.name; item.glyph = emoji.glyph; }
const cardTitle = id => { const card = cards.value.find(row => row.id === id); return card ? (card.name || card.title) : ''; };
const describe = item => item.type === 'emoji' ? (item.name ? `[表情] ${item.glyph || ''}${item.name}` : '未选择表情') : item.type === 'card' ? (item.cardId ? `[卡片] ${cardTitle(item.cardId) || '卡片已删除'}` : '未选择卡片') : item.type === 'image' ? (item.imageId ? `[图片] ${item.name || ''}` : '未上传图片') : (item.text || '未填写内容');
async function pickImage(item, event) {
  const file = event.target.files?.[0]; event.target.value = '';
  if (!file) return;
  if (!/^image\/(jpeg|png|gif|webp)$/.test(file.type)) { localError.value = '仅支持 JPG、PNG、GIF、WEBP 图片。'; return; }
  if (file.size > 3 * 1024 * 1024) { localError.value = '图片不能超过 3MB。'; return; }
  uploading.value = true; localError.value = '';
  try {
    const bytes = new Uint8Array(await file.arrayBuffer());
    let binary = '';
    for (let offset = 0; offset < bytes.length; offset += 0x8000) binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000));
    let width = 0, height = 0;
    try { const bitmap = await createImageBitmap(file); width = bitmap.width; height = bitmap.height; bitmap.close?.(); } catch { /* 尺寸可选 */ }
    const saved = await apiRequest('reply-rule-images', { method: 'POST', body: { data: btoa(binary), name: file.name.slice(0, 120), width, height }, timeoutMs: 30000 });
    item.imageId = saved.id; item.name = saved.name; item.preview = URL.createObjectURL(file);
  } catch (cause) { localError.value = cause.message; } finally { uploading.value = false; }
}
function componentError(item, index) {
  const label = `第 ${index + 1} 个组件`;
  if (item.type === 'text') return item.text.trim() ? '' : `${label}：请填写文本。`;
  if (item.type === 'emoji') return item.name ? '' : `${label}：请选择表情。`;
  if (item.type === 'card') return item.cardId ? '' : `${label}：请选择卡片。`;
  if (item.type === 'image') return item.imageId ? '' : `${label}：请上传图片。`;
  return `${label}：类型无效。`;
}
const payloadComponent = item => item.type === 'emoji' ? { type: 'emoji', name: item.name, glyph: item.glyph } : item.type === 'card' ? { type: 'card', cardId: item.cardId } : item.type === 'image' ? { type: 'image', imageId: item.imageId, name: item.name || '' } : { type: 'text', mode: item.mode, text: item.text };
function move(index, delta) { const other = index + delta; if (other < 0 || other >= form.components.length) return; [form.components[index], form.components[other]] = [form.components[other], form.components[index]]; }
const keywordList = computed(() => [...new Set(form.keywords.split(/\r?\n|,|，/).map(word => word.trim()).filter(Boolean))]);
function submit() { if (!form.account) { localError.value = '请选择监听账号。'; return; } if (form.trigger === 'keyword' && !keywordList.value.length) { localError.value = '请至少填写一个触发关键词。'; return; } for (const [index, item] of form.components.entries()) { const problem = componentError(item, index); if (problem) { localError.value = problem; return; } } if (uploading.value) { localError.value = '图片正在上传，请稍候。'; return; } const dailyLimit = form.dailyLimit === '' ? null : Number(form.dailyLimit); if (dailyLimit !== null && (!Number.isInteger(dailyLimit) || dailyLimit < 1)) { localError.value = '每日响应次数必须是正整数或留空。'; return; } localError.value = ''; emit('save', { scope: group.value ? 'group' : 'direct', name: form.name, account: form.account, trigger: form.trigger, keywords: form.trigger === 'keyword' ? keywordList.value : [], dailyLimit, delay: Number(form.delay), cooldown: group.value ? Number(form.cooldown) : 0, groups: form.groups, components: form.components.map(payloadComponent), recall: false, enabled: form.enabled }); }
</script>
<template><el-dialog :model-value="true" :title="(initial?'编辑':'新增') + kind" width="min(1000px, 94vw)" @close="emit('close')" destroy-on-close><div class="rule-editor"><el-form label-position="top" class="rule-fields"><h3>规则配置</h3><el-form-item label="自动回复名称"><el-input v-model="form.name" placeholder="可选，不填写时自动生成名称"/></el-form-item><el-form-item label="监听账号" required><el-select v-model="form.account" placeholder="请选择监听账号"><el-option v-for="account in accounts" :key="account.id" :label="account.nickname||account.name" :value="account.id"/></el-select><small>自动回复会同时使用这个账号作为监听账号和执行账号。</small></el-form-item><el-form-item v-if="group" label="监听群聊"><el-select v-model="form.groups" placeholder="不选择表示监听该账号的全部群聊" multiple allow-create filterable><el-option v-for="item in groupOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select><small>已选择 {{ form.groups.length }} 个群聊；留空时匹配全部群聊。</small></el-form-item><el-form-item label="触发类型"><el-select v-model="form.trigger"><el-option :label="group?'任意群聊文本消息':'首次私聊回复'" :value="group?'any':'first'"/><el-option label="特定关键词" value="keyword"/></el-select></el-form-item><el-form-item v-if="form.trigger==='keyword'" label="触发关键词" required><el-input v-model="form.keywords" type="textarea" :rows="3" placeholder="每行一个关键词，消息包含任意一个即触发"/><small>每行一个关键词（不区分大小写），消息中包含任意一个就会触发；已填写 {{ keywordList.length }} 个。关键词规则优先于“任意文本消息”规则。</small></el-form-item><el-form-item :label="group?'同一群聊每天最多响应次数':'同一用户每天最多响应次数'"><el-input v-model="form.dailyLimit" placeholder="留空表示不限" inputmode="numeric"/></el-form-item><el-form-item label="触发延迟（秒）"><el-input-number v-model="form.delay" :min="0" :max="86400" :precision="0"/></el-form-item><el-form-item v-if="group" label="发送消息冷却（分钟）"><el-input-number v-model="form.cooldown" :min="0" :max="1440" :precision="0"/></el-form-item><el-form-item label="发送通道"><el-select model-value="default" disabled><el-option label="默认通道" value="default"/></el-select></el-form-item><div class="component-heading"><h3>回复组件（按顺序发送）</h3><el-dropdown trigger="click" @command="addComponent"><el-button>增加组件<el-icon class="el-icon--right"><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="text">文本</el-dropdown-item><el-dropdown-item command="emoji">表情</el-dropdown-item><el-dropdown-item command="image">图片</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><section v-for="(item,index) in form.components" :key="item.id" class="reply-component"><div class="component-heading"><strong>{{ index+1 }}　{{ typeLabels[item.type] || '文本回复' }}</strong><div><el-button size="small" :disabled="index===0" @click="move(index,-1)">上移</el-button><el-button size="small" :disabled="index===form.components.length-1" @click="move(index,1)">下移</el-button><el-button size="small" :disabled="form.components.length===1" @click="form.components.splice(index,1)">删除</el-button></div></div><template v-if="item.type==='text'"><el-radio-group v-model="item.mode"><el-radio value="whole">整条发送</el-radio><el-radio value="random">随机文本</el-radio></el-radio-group><el-input v-model="item.text" type="textarea" :rows="4" maxlength="1000" show-word-limit :placeholder="item.mode==='random'?'每行一条文本，发送时随机选其中一行（按回车换行）':'请输入自动回复文本'"/><small v-if="item.mode==='random'">随机文本：按回车分隔，每次随机发送其中一行（当前 {{ item.text.split(/\r?\n/).filter(line=>line.trim()).length }} 行）。</small></template><template v-else-if="item.type==='emoji'"><div class="emoji-grid"><button v-for="emoji in emojis" :key="emoji.name" type="button" class="emoji-option" :class="{selected:item.name===emoji.name}" :aria-label="emoji.name" :aria-pressed="item.name===emoji.name" @click="pickEmoji(item,emoji)"><span>{{ emoji.glyph }}</span><small>{{ emoji.name }}</small></button></div><small>{{ item.name ? '已选择：'+(item.glyph||'')+item.name : '请选择一个表情。' }}嗨、比心、续火花会以抖音图片表情发送，其余按文本表情发送。</small></template><template v-else-if="item.type==='card'"><el-select v-model="item.cardId" filterable placeholder="请选择统一卡片"><el-option v-for="card in cards" :key="card.id" :label="card.name||card.title" :value="card.id"/></el-select><small v-if="!cards.length">还没有可用卡片，请先在“统一卡片”中创建。</small><small v-else>发送时使用该卡片当前配置的企业微信、QQ 或公众号文章直链；没有直链的卡片会被跳过。</small></template><template v-else-if="item.type==='image'"><label class="image-pick"><input type="file" accept="image/jpeg,image/png,image/gif,image/webp" :disabled="uploading" @change="pickImage(item,$event)"/><span>{{ uploading ? '上传中…' : item.imageId ? '重新选择图片' : '选择图片' }}</span></label><img v-if="item.preview" :src="item.preview" :alt="item.name||'已上传图片'" class="image-preview"/><small>{{ item.imageId ? '已上传：'+(item.name||'图片') : '支持 JPG、PNG、GIF、WEBP，不超过 3MB。' }}</small></template></section><el-form-item label="启用状态"><el-switch v-model="form.enabled" active-text="启用" inactive-text="禁用"/></el-form-item></el-form><aside class="rule-preview"><h3>规则预览</h3><dl><dt>自动回复名称</dt><dd>{{ form.name || '保存时自动生成' }}</dd><dt>监听账号</dt><dd>{{ accounts.find(item=>item.id===form.account)?.name || '未选择' }}</dd><dt>触发条件</dt><dd>{{ form.trigger==='keyword' ? (keywordList.length ? '消息包含：'+keywordList.join('、') : '消息包含关键词（未填写）') : (group?'收到任意群聊文本消息时触发':'对方第一次私信时触发（每个会话只回复一次）') }}</dd><dt>触发延迟</dt><dd>{{ form.delay?form.delay+' 秒':'立即执行' }}</dd><template v-if="group"><dt>发送消息冷却</dt><dd>{{ form.cooldown?form.cooldown+' 分钟':'不限制' }}</dd></template><dt>每天最多响应次数</dt><dd>{{ form.dailyLimit || '不限' }}</dd><dt>回复组件</dt><dd v-for="(item,index) in form.components" :key="item.id">{{ index+1 }}. {{ describe(item) }}</dd></dl></aside></div><el-alert v-if="localError||error" :title="localError||error" type="error" :closable="false"/><template #footer><el-button @click="emit('close')">取消</el-button><el-button type="primary" :loading="saving" @click="submit">{{ initial?'保存':'创建' }}{{ kind }}</el-button></template></el-dialog></template>
<style scoped>.rule-editor{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:26px}.rule-fields{max-height:65vh;overflow:auto;padding-right:12px}.rule-fields small{display:block;color:#97a1b2;line-height:1.7;margin-top:5px}.rule-preview{background:#f6f9ff;border:1px solid #e9eff9;border-radius:12px;padding:18px;overflow:auto;max-height:65vh}.rule-preview h3{margin-top:0}.rule-preview dt{font-size:12px;color:#9aa5b7;margin-top:17px}.rule-preview dd{margin:7px 0;color:#54657e;font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}.component-heading{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:12px}.component-heading h3{font-size:14px}.reply-component{padding:14px;border:1px solid #e5ebf5;border-radius:10px;margin-bottom:16px}.el-select{width:100%}.emoji-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(64px,1fr));gap:8px}.emoji-option{display:grid;gap:2px;justify-items:center;padding:8px 4px;border:1px solid #e2e8f3;border-radius:8px;background:#fbfcff;cursor:pointer;font-size:22px}.emoji-option small{margin:0;font-size:12px}.emoji-option.selected{border-color:#4d7ff3;box-shadow:0 0 0 2px #4d7ff322;background:#f4f7ff}.image-pick{display:inline-block;padding:7px 14px;border:1px solid #dcdfe6;border-radius:6px;cursor:pointer;font-size:13px}.image-pick input{position:absolute;width:1px;height:1px;opacity:0}.image-pick:focus-within{outline:2px solid #4d7ff3}.image-preview{display:block;max-width:160px;max-height:160px;margin-top:10px;border-radius:8px}@media(max-width:720px){.rule-editor{grid-template-columns:1fr}.rule-preview{max-height:30vh}}</style>
